#!/usr/bin/env node
// Generates src/model/logic.generated.js from the logic class in mockups/portal/Main.dc.html, so the mockup stays the
// single source until the API exists. With --check it fails if the generated file is out of date.
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const app = join(dirname(fileURLToPath(import.meta.url)), "..");
const source = readFileSync(join(app, "..", "mockups", "portal", "Main.dc.html"), "utf8");
const output = join(app, "src", "model", "logic.generated.js");

const open = source.indexOf("data-dc-script");
const script = source.slice(source.indexOf(">", open) + 1, source.lastIndexOf("</script>"));
const tag = source.slice(open, source.indexOf(">", open));
const props = /data-props='([^']*)'/.exec(tag);
if (!props) throw new Error("no data-props on the logic script");
const generated = `// Generated by scripts/extract-model.mjs from mockups/portal/Main.dc.html. Do not edit.
import { DCLogic } from "./dclogic";
export const PROPS = ${props[1]};
${script.replace(/^class Component extends DCLogic/m, "export class Component extends DCLogic")}`;
if (generated === script || !generated.includes("export class Component")) throw new Error("no Component class found");

if (process.argv.includes("--check")) {
  if (!existsSync(output) || readFileSync(output, "utf8") !== generated) {
    console.error("src/model/logic.generated.js is out of date: run npm run model");
    process.exit(1);
  }
} else {
  writeFileSync(output, generated);
}
